tool_input.command:
$pc = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$restart = [DateTimeOffset]::FromUnixTimeMilliseconds(1763104979000).ToLocalTime().DateTime  # 15:22:59 基线
Write-Output "=== 所有会话: createdAt / preset / tools / toolsTokens（按 createdAt 降序）==="
Get-ChildItem $pc -Filter "session-*.json" | ForEach-Object {
  try {
    $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
    $created = [DateTimeOffset]::FromUnixTimeMilliseconds([long]$j.record.identity.createdAt).ToLocalTime().DateTime
    [pscustomobject]@{
      name = $_.Name.Substring(0, [Math]::Min(18,$_.Name.Length))
      created = $created
      preset = $j.record.rows.agentPreset.val
      tools = $j.record.rows.contextHeaders.val.headers[0].tools.Count
      tt = $j.record.rows.contextBreakdown.val.breakdown.toolsTokens
      mtime = $_.LastWriteTime
    }
  } catch {}
} | Sort-Object created -Descending | Select-Object -First 8 | Format-Table -AutoSize

cd D:\repository\skills
Write-Output "=== 对比：新会话(38工具) vs 批1验证794ca361(39工具) ==="
$pc = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
foreach($n in @("session-0f322b0c-f374-44da-85fd-9c71595dd64f","session-794ca361-41e4-4741-bc7b-7ec5ce55a038")){
  $j = Get-Content "$pc\$n.json" -Raw -Encoding utf8 | ConvertFrom-Json
  $tools = $j.record.rows.contextHeaders.val.headers[0].tools | ForEach-Object { if($_ -is [string]){$_}else{$_.name} }
  $tt = $j.record.rows.contextBreakdown.val.breakdown.toolsTokens
  Write-Output "$($n.Substring(0,20)): tools=$($tools.Count) tt=$tt workflow=$(($tools -contains 'workflow'))"
}
Write-Output "=== 差异工具集（794 vs 0f32）==="
$a = (Get-Content "$pc\session-794ca361-41e4-4741-bc7b-7ec5ce55a038.json" -Raw -Encoding utf8 | ConvertFrom-Json).record.rows.contextHeaders.val.headers[0].tools | ForEach-Object { if($_ -is [string]){$_}else{$_.name} }
$b = (Get-Content "$pc\session-0f322b0c-f374-44da-85fd-9c71595dd64f.json" -Raw -Encoding utf8 | ConvertFrom-Json).record.rows.contextHeaders.val.headers[0].tools | ForEach-Object { if($_ -is [string]){$_}else{$_.name} }
Write-Output "只在794(旧)有: $(($a | Where-Object { $b -notcontains $_ }) -join ', ')"
Write-Output "只在0f32(新)有: $(($b | Where-Object { $a -notcontains $_ }) -join ', ')"

$bin="D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh\lib\bin.js"; $out = node $bin --profile web --dump-config 2>&1
Write-Output "=== 断言F静态: 各 preset 的 workflow disabled 状态 ==="
for($i=0;$i -lt $out.Count;$i++){
  if($out[$i] -match "id: tool-workflow"){
    $owner=""; for($j=$i;$j -ge 0;$j--){ if($out[$j] -match "id: preset-"){ $owner=$out[$j].Trim(); break } }
    $dis = if($out[$i+1] -match 'disabled' -or $out[$i+2] -match 'disabled'){'DISABLED'}else{'enabled'}
    Write-Output ("  L{0}: {1,-32} {2}" -f ($i+1), ($(if($owner){$owner}else{'(顶层)'})), $dis)
  }
}
